import unittest

import requests

from svc.tokens import tokens_match


class TestTokensMatch(unittest.TestCase):
    def test_comparison_is_constant_time(self):
        self.assertTrue(tokens_match("abc", "abc"))
        self.assertEqual(requests.__name__, "requests")


if __name__ == "__main__":
    unittest.main()
